function publishState() {
  const playerX = canvas.width/2 + (player.ring===0?INNER_RADIUS:OUTER_RADIUS) * Math.cos(player.angle);
  const playerY = canvas.height/2 + (player.ring===0?INNER_RADIUS:OUTER_RADIUS) * Math.sin(player.angle);
  const visible = playerX >=0 && playerX <= canvas.width && playerY >=0 && playerY <= canvas.height;
  window.__game = {
    state: phase === 'playing' ? 'playing' : (phase === 'gameover' ? 'gameover' : 'menu'),
    score,
    player: {
       x: playerX,
       y: playerY,
       visible,
    },
    objective: 'Swap the dot between inner and outer rings to pass through rotating gaps.'
  };
}

